mapper.select:
SELECT p.id, p.product_code, p.title, p.brand, p.image_url, p.category_id, c.name AS category_name, p.specification, p.description, p.status, p.created_at, p.updated_at FROM product p LEFT JOIN category c ON c.id = p.category_id WHERE p.deleted = 0
AND p.category_id = #{categoryId}
AND p.status = #{status}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!' OR p.brand LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!' OR p.product_code LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!')
ORDER BY p.created_at DESC, p.id DESC
